contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address coordinator, UFixed18 newMakerFee) public {
        require(coordinator != address(0));

        // Change the maker fee. Depending on the product state, the library either
        // stores it immediately as the effective maker fee or keeps it in the
        // pending fee updates. This call is part of the environment setup and may
        // revert if the caller is not the product owner; the assertion below only
        // concerns whether a pending maker fee update was recorded.
        bool callOk;
        try c.updateMakerFee(newMakerFee) {
            callOk = true;
        } catch {
            callOk = false;
        }

        PendingFeeUpdates memory pending = c.pendingFeeUpdates();

        // The general rule: if the call succeeded and a pending maker fee update
        // was recorded, its value must equal the requested maker fee.
        assert(!callOk || !pending.makerFeeUpdated || pending.pendingMakerFee() == newMakerFee);
    }
}

