contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        // Read the before state relevant to the position-fee rule.
        uint256 beforeVersion = c.latestVersion();
        UFixed18 beforeCollateral = c.collateral(address(this));
        UFixed18 takerFee_ = c.takerFee();

        // The deciding state-changing call.
        c.openTake(UFixed18.wrap(amount));

        // The general rule: the position fee charged by openTake equals
        // amount * price * takerFee exactly, and is reflected as a decrease in
        // the account's collateral (when nonzero).
        UFixed18 afterCollateral = c.collateral(address(this));
        IOracleProvider.OracleVersion memory ov = c.atVersion(beforeVersion);
        UFixed18 expectedFee = UFixed18.wrap(
            amount * UFixed18.unwrap(ov.price.abs()) / 1e18
        ).mul(takerFee_);

        // Either no fee was charged (expectedFee is zero and collateral is unchanged),
        // or the fee was charged and is the exact difference in collateral.
        assert(
            expectedFee.isZero()
                ? UFixed18.eq(afterCollateral, beforeCollateral)
                : UFixed18.eq(UFixed18.wrap(UFixed18.unwrap(beforeCollateral) - UFixed18.unwrap(afterCollateral)), expectedFee)
        );
    }

    receive() external payable {}
}

