        }

        // General rule: two consecutive openTake calls on a fresh product cannot both succeed
        // and alter the position, because no oracle bootstrapping/settlement has occurred.
        // If both calls somehow return without reverting, the product must still report zero
        // taker position for this account — otherwise a broken implementation would violate this.
        if (!firstReverted && !secondReverted) {
            Position memory p = c.position(address(this));
            assert(UFixed18.unwrap(p.taker) == 0 && UFixed18.unwrap(p.maker) == 0);
        } else {
            // At least one reverted is the expected safe behavior.
            assert(firstReverted || secondReverted);
        }
    }
}

